            for (int i = 1; i <= colCount; i++) {
                resultStr.append(resultSet.getString(i)).append(",");
            }
            resultStr.append("\n");
        }
        Assert.assertEquals(resultStr.toString(), standard);
    } catch (SQLException e) {
        System.out.println(e);
    }
}

